effect.shader:
// -----------------------------------------------
// Color helpers
// -----------------------------------------------
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz)*6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p-K.xxx, 0.0, 1.0), c.y);
}

vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0,-1.0/3.0,2.0/3.0,-1.0);
    vec4 p = mix(vec4(c.bg,K.wz), vec4(c.gb,K.xy), step(c.b,c.g));
    vec4 q = mix(vec4(p.xyw,c.r), vec4(c.r,p.yzx), step(p.x,c.r));
    float d = q.x - min(q.w,q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w-q.y)/(6.0*d+e)), d/(q.x+e), q.x);
}

float luma(vec3 c) { return dot(c, vec3(0.2126,0.7152,0.0722)); }

// sRGB <-> linear
vec3 toLinear(vec3 c) {
    return mix(c/12.92, pow(max((c+0.055)/1.055,vec3(0.0001)),vec3(2.4)),
               step(vec3(0.04045),c));
}
vec3 toSRGB(vec3 c) {
    c = max(c,vec3(0.0));
    return mix(c*12.92, 1.055*pow(c,vec3(1.0/2.4))-0.055,
               step(vec3(0.0031308),c));
}

// -----------------------------------------------
// Convert hue-disc to offset RGB color
// hue-disc returns: x=hue(0-360), y=saturation, z=bias
// When sat=0 and bias=0 → no change (neutral)
// -----------------------------------------------
vec3 wheelToOffset(vec3 wheel) {
    float hue = wheel.x / 360.0;
    float sat = wheel.y;
    float bias = wheel.z; // bias = strength of the wheel
    if (sat < 0.001) return vec3(0.0);
    vec3 col = hsv2rgb(vec3(hue, sat, 1.0));
    // Center around gray (offset from 0.5)
    return (col - 0.5) * sat * 0.15;
}

// -----------------------------------------------
// Apply tone curve — simple 3-point bezier
// shadow, mid, highlight control points
// -----------------------------------------------
float applyCurve(float v) {
    // Normalize curve control points
    float s = curveShadow + 0.0;    // shadow point (input 0)
    float m = curveMid;              // midpoint (input 0.5)
    float h = curveHigh;             // highlight (input 1.0)

    // Piecewise linear through 3 points
    if (v < 0.5) {
        return mix(s, m, v * 2.0);
    } else {
        return mix(m, h, (v - 0.5) * 2.0);
    }
}

// -----------------------------------------------
// Temperature/Tint — shifts white balance
// Temperature: warm(+) = more red/yellow, cool(-) = more blue
// Tint: green(+) or magenta(-)
// -----------------------------------------------
vec3 applyWhiteBalance(vec3 col, float temp, float tintV) {
    float t = temp / 100.0;
    float g = tintV / 100.0;
    col.r += t * 0.1;
    col.b -= t * 0.1;
    col.g += g * 0.05;
    col.r -= g * 0.025;
    col.b -= g * 0.025;
    return col;
}

void main() {
    vec2 uv  = acScreenNorm;
    vec4 src = texture2DCv(inputImg.texture, clamp(uv,0.0,1.0));
    vec3 col = src.rgb;
    vec3 raw = col;

    // Work in linear light
    vec3 lin = toLinear(col);

    // -----------------------------------------------
    // EXPOSURE — multiply in linear space
    // -----------------------------------------------
    lin *= pow(2.0, exposure);

    // -----------------------------------------------
    // CONTRAST — S-curve around middle gray
    // -----------------------------------------------
    if (abs(contrast) > 0.001) {
        float pivot = 0.18;
        lin = (lin - pivot) * (1.0 + contrast) + pivot;
    }

    // Back to sRGB for color wheel operations
    col = toSRGB(max(lin, vec3(0.0)));

    // -----------------------------------------------
    // THREE-WAY COLOR WHEELS
    // Shadows affect dark areas, Highlights affect bright
    // Midtones affect mid-range luminance
    // -----------------------------------------------
    float lum = luma(col);

    // Zone masks — smooth overlap between zones
    float shadowMask    = 1.0 - smoothstep(0.0, 0.5, lum);
    float highlightMask = smoothstep(0.5, 1.0, lum);
    float midtoneMask   = 1.0 - shadowMask - highlightMask;
    midtoneMask = max(midtoneMask, 0.0);

    // Get color offsets from each wheel
    vec3 shadowOffset    = wheelToOffset(vec3(shadowsWheel.x,    shadowsWheel.y,    shadowsWheel.z));
    vec3 midtoneOffset   = wheelToOffset(vec3(midtonesWheel.x,   midtonesWheel.y,   midtonesWheel.z));
    vec3 highlightOffset = wheelToOffset(vec3(highlightsWheel.x, highlightsWheel.y, highlightsWheel.z));

    // Apply wheels weighted by zone masks
    col += shadowOffset    * shadowMask;
    col += midtoneOffset   * midtoneMask;
    col += highlightOffset * highlightMask;

    // -----------------------------------------------
    // TEMPERATURE / TINT
    // -----------------------------------------------
    col = applyWhiteBalance(col, temperature, tint);

    // -----------------------------------------------
    // TONE CURVE — apply per channel + master
    // -----------------------------------------------
    float masterR = applyCurve(col.r) + liftR;
    float masterG = applyCurve(col.g) + liftG;
    float masterB = applyCurve(col.b) + liftB;
    col = vec3(masterR, masterG, masterB);

    // -----------------------------------------------
    // HUE SHIFT + SATURATION
    // -----------------------------------------------
    vec3 hsv = rgb2hsv(clamp(col, 0.0, 1.0));
    hsv.x = fract(hsv.x + hueShift/360.0);
    hsv.y = clamp(hsv.y * saturation, 0.0, 1.0);
    col = hsv2rgb(hsv);

    col = clamp(col, 0.0, 1.0);

    // Strength blend
    col = mix(raw, col, strength);

    // Overall blend
    gl_FragColor = vec4(mix(raw, col, blend), src.a);
}
